    /** The figures of a sheet's descendants added up (all zero when it has none). */
    @Transactional(readOnly = true)
    public Descendants descendants(String sheetId) {
        int count = 0;
        BigDecimal due = BigDecimal.ZERO.setScale(2);
        BigDecimal overdue = BigDecimal.ZERO.setScale(2);
        for (String id : sheetStore.descendants(sheetId)) {
            Snapshot s = snapshot(id);
            count += s.people().size();
            due = due.add(new BigDecimal(s.dueTotal()));
            overdue = overdue.add(new BigDecimal(s.overdueTotal()));
        }
        Snapshot own = snapshot(sheetId);
        return new Descendants(count, text(due), text(overdue), own.people().size(), own.dueTotal(),
                own.overdueTotal());
    }

    private Snapshot snapshot(String sheetId) {
        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        LocalDate today = sheets.today(sheetId);
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            List<Claim> theirs = Dues.live(person, byPerson.getOrDefault(person.getId(), List.of()), today);
            BigDecimal claimed = theirs.stream().map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            BigDecimal due = dues.dueTotal(sheetId, person, theirs);
            BigDecimal overdue = theirs.stream().filter(c -> dues.overdue(sheetId, person, c))
                    .map(c -> dues.figure(sheetId, person, c)).filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            overdueFigures.add(overdue);
            if (due != null) {
                dueFigures.add(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), text(claimed),
                    due == null ? "n/a" : text(due), text(overdue)));
        }
        return new Snapshot(figures, text(claimedTotal), text(trimmedSum(dueFigures)), text(trimmedSum(overdueFigures)));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are
     *  three or more. */
    for (const x of this.plans()) by.set(x.personId, [...(by.get(x.personId) ?? []), x]);
    return by;
  });
  /** The people the signed-in user watches, in the order they started watching. */
  protected readonly watches = signal<Watch[]>([]);
  /** The ids of the people the signed-in user watches. */
  protected readonly watched = computed(() => new Set(this.watches().map((w) => w.personId)));
  /** Each person, by id: their holds and retirement leave claims out of the live totals. */
  private readonly byId = computed(() => new Map(this.people().map((p) => [p.id, p])));
  /** The claims that count in the live totals, newest first. */
  private readonly live = computed(() => this.claims().filter((c) => countsLive(c, this.byId().get(c.personId) ?? NO_LEAVE, this.session.today())));
  /** What each person has claimed: the sum of their open and settled claims' amounts, leaving out
   *  the open ones dated within one of their holds and unbound by a statement. */
  protected readonly claimed = computed(() => {
    const by = new Map<number, string>();
    for (const [id, cs] of this.claimsByPerson()) {
      by.set(id, sumAmounts(cs.filter((c) => countsLive(c, this.byId().get(id) ?? NO_LEAVE, this.session.today())).map((c) => c.amount)));
    }
    return by;
  });
  protected readonly claimedTotal = computed(() => sumAmounts(this.live().map((c) => c.amount)));
  /** The rates set on the sheet. */
  protected readonly rates = signal<Rate[]>([]);
  /** The sheet's floors recorded: the least live due a claim has is the one in force on its date. */
  protected readonly floor = signal<DatedValue[]>([]);
  /** The sheet's caps recorded (null: no cap), each from its from-date. */
